/* One captured cube, one beginner curriculum, and reversible human-paced instructions. */
const LessonFlow=(()=>{
const VERSION='cube-consistent-v2';
const E=[[5,10],[7,19],[3,37],[1,46],[32,16],[28,25],[30,43],[34,52],[23,12],[21,41],[50,39],[48,14]],C=[[8,9,20],[6,18,38],[0,36,47],[2,45,11],[29,26,15],[27,44,24],[33,53,42],[35,17,51]],EC=['UR','UF','UL','UB','DR','DF','DL','DB','FR','FL','BL','BR'],CC=['URF','UFL','ULB','UBR','DFR','DLF','DBL','DRB'];
const lower=c=>fixedEdges(c,[4,5,6,7,8,9,10,11])&&fixedCorners(c,[4,5,6,7]);
let state=null,model=null,job=null,loading='',error='',moving=false,preview=false,demoCursor=0,demoToken=0,demoStop=false,view='F',labSession=null,labDone=false,allFaces=false,chosenFace=null;
function read(mode='camera'){try{const o=JSON.parse(localStorage.getItem(VERSION+'-'+mode)||'null');return o&&o.mode===mode&&o.current?.length===54?o:null;}catch{return null;}}
function save(){if(!state||labSession)return;try{localStorage.setItem(VERSION+'-camera',JSON.stringify(state));localStorage.setItem(VERSION+'-mode','camera');}catch{}}
function fresh(str){const c=valid(str);return{flowVersion:4,mode:'camera',initial:str,current:str,practice:str,stage:detect(c),plan:null,guideCursor:0,trail:[],history:[],completed:[],stageReady:false,feedback:'',revision:0};}
function prerequisites(c,n){if(n===0)return true;if(n===1)return[4,5,6,7].every(p=>c.ep[p]===p&&c.eo[p]===0||c.ep.indexOf(p)<4&&c.eo[c.ep.indexOf(p)]===0);return milestone(c,n-1);}
function migrate(o){if(o.flowVersion===4)return{...o,trail:o.trail||[],guideCursor:o.guideCursor||0};const actual=([4,5].includes(o.phase)||o.phase===3&&o.resumePractice||o.flowVersion===3)?o.practice||o.current:o.current;const n=o.stage??detect(Cube.fromString(actual));return{...o,flowVersion:4,mode:'camera',initial:o.initial||o.current,current:o.current,practice:actual,stage:n,plan:o.plan||null,history:o.history||[],trail:[],guideCursor:0,completed:o.completed||[],revision:o.revision||0,stageReady:!!o.stageReady||(n<8&&milestone(Cube.fromString(actual),n)),needsRebase:actual!==o.current,offTrack:false,feedback:''};}
function restore(){cancelJob();demoToken++;preview=false;moving=false;loading='';error='';view='F';if(!state)return;state=migrate(state);model=Cube.fromString(state.practice||state.current);if(state.needsRebase&&!state.stageReady){state.offTrack=!prerequisites(model,state.stage);if(!state.offTrack)state.plan=null;state.needsRebase=false;}save();if(state.stage<8&&!state.plan&&!state.offTrack)prepare();}
function cancelJob(){job?.terminate();job=null;}
function prepare(){if(!state||state.stage>=8||state.stageReady||state.offTrack)return;cancelJob();const origin=state.practice||state.current,revision=++state.revision,owner=state;loading='내 큐브의 다음 동작을 준비하고 있어요…';error='';const worker=new Worker('worker.js?v=human-teacher-1');job=worker;const timeout=setTimeout(()=>{if(job!==worker)return;worker.terminate();job=null;loading='';error='준비 시간이 길어졌어요. 현재 큐브는 저장돼 있어요.';render();},45000);worker.onmessage=e=>{if(e.data.type==='progress')return;if(job!==worker||owner!==state||state.revision!==revision)return;clearTimeout(timeout);worker.terminate();job=null;loading='';if(e.data.type==='error'){error=e.data.message;render();return;}state.plan=e.data.stages;state.current=origin;state.practice=origin;state.guideCursor=0;state.history=[];while(state.stage<8&&!state.plan[state.stage].moves.length){if(!state.completed.includes(state.stage))state.completed.push(state.stage);state.stage++;}model=Cube.fromString(origin);view=lessonView();save();if(route==='learn'||route==='practice')render();};worker.onerror=()=>{clearTimeout(timeout);if(job!==worker)return;worker.terminate();job=null;loading='';error='동작을 준비하지 못했어요. 현재 큐브는 그대로 저장돼 있어요.';render();};worker.postMessage({facelets:origin,startStage:state.stage});}
function routeToLesson(){if(location.hash==='#learn')render();else location.hash='#learn';}
function openCaptured(str){valid(str);if(labSession)leaveLab(false);save();state=fresh(str);restore();routeToLesson();}
function stage(){return state.plan[state.stage];}
function segment(){return stage().segments[0];}
function moves(){const s=segment();return stage().moves.slice(s.start,s.end);}
function descriptor(){return CubeTeacher.focus(Cube.fromString(segment().initial),state.stage,segment());}
function targetColors(){return CubeTeacher.targetName({...segment(),...descriptor()});}
function practiceGoal(c){return segmentGoal(c,state.stage,descriptor(),Cube.fromString(state.current));}
function lessonView(){if(!state?.plan||state.stage>=8)return'F';const side=moves().find(m=>m[0]!=='U'&&m[0]!=='D')?.[0];return side==='L'?'L':side==='B'?'B':'F';}
function instruction(){return CubeTeacher.instruction(model,state.stage,segment(),moves(),preview?demoCursor:state.guideCursor);}
function activeLesson(){const s=segment(),seq=moves(),patterns=CubeTeacher.patterns(s,seq,state.stage).map(p=>({...p,start:p.start-s.start,end:p.end-s.start}));return{...stage(),initial:state.current,moves:seq,segments:[{...s,start:0,end:seq.length,patterns}],final:s.final};}
function checkpoint(move=null){return{move,stage:state.stage,current:state.current,practice:state.practice,guideCursor:state.guideCursor,stageReady:state.stageReady,completed:[...state.completed],lesson:state.stage<8&&state.plan?activeLesson():null};}
function remember(move){state.trail.push(checkpoint(move));}
function lockControls(){if(typeof document==='undefined')return;document.querySelectorAll('.teacher-dock button').forEach(b=>b.disabled=true);}
function restoreCheckpoint(c){state.stage=c.stage;state.current=c.current;state.practice=c.practice;state.guideCursor=c.guideCursor;state.stageReady=c.stageReady;state.completed=c.completed;state.history=[];state.offTrack=false;state.plan=[];if(c.lesson)state.plan[c.stage]=c.lesson;model=Cube.fromString(c.practice);view=lessonView();}
function acceptResult(){if(!practiceGoal(model))return false;state.current=model.asString();state.practice=state.current;state.history=[];state.guideCursor=0;state.feedback='';if(milestone(model,state.stage)){state.stageReady=true;if(!state.completed.includes(state.stage))state.completed.push(state.stage);save();return true;}state.plan=null;save();prepare();return true;}
async function next(){if(!state||moving||busy||preview||labSession||loading||error||state.offTrack||state.stage>=8)return;if(state.stageReady){remember(null);state.stage++;state.stageReady=false;state.plan=null;state.guideCursor=0;state.feedback='';save();prepare();render();return;}const m=moves()[state.guideCursor];if(!m)return;remember(m);moving=true;lockControls();await turn(model,m,'flow-cube');state.practice=model.asString();state.guideCursor++;state.feedback='';moving=false;if(state.guideCursor===moves().length){if(!acceptResult()){state.offTrack=true;state.feedback='묶음 결과를 확인하지 못했어요. 이전 동작으로 돌아가거나 현재 큐브를 다시 촬영해주세요.';save();}}else save();render();}
async function previous(){if(!state||moving||busy||preview||labSession||loading)return;if(state.trail.length){const c=state.trail.at(-1);moving=true;lockControls();if(c.move)await turn(model,Cube.inverse(c.move),'flow-cube');state.trail.pop();restoreCheckpoint(c);moving=false;state.feedback=c.move?`실물도 ${CubeTeacher.turnText(Cube.inverse(c.move))}. 화면과 같아졌는지 확인한 뒤 이어가세요.`:'이전 목표의 완성 상태예요. 실물 큐브는 그대로 두세요.';save();render();return;}if(state.history.length){const h=state.history.pop();moving=true;await turn(model,Cube.inverse(h.move),'flow-cube');model=Cube.fromString(h.before);state.practice=h.before;moving=false;if(state.offTrack&&prerequisites(model,state.stage)){state.offTrack=false;state.current=h.before;state.plan=null;prepare();}save();render();}}
function labStart(){if(!state||!state.plan||state.stage>=8||moving||loading||preview||labSession)return false;labSession={state,model:model.asString(),view};const lesson=activeLesson(),origin=segment().initial;lesson.initial=origin;state={...fresh(origin),stage:state.stage,plan:[],current:origin,practice:origin};state.plan[state.stage]=lesson;model=Cube.fromString(origin);labDone=false;allFaces=false;chosenFace=null;return true;}
function leaveLab(show=true){if(!labSession)return;cancelJob();demoToken++;preview=false;moving=false;state=labSession.state;model=Cube.fromString(labSession.model);view=labSession.view;labSession=null;labDone=false;loading='';error='';if(show){if(location.hash==='#learn')render();else location.hash='#learn';}}
async function act(move){if(!labSession||moving||busy||preview||labDone)return;moving=true;const before=model.asString();await turn(model,move,'flow-cube');state.history.push({before,move});state.practice=model.asString();state.feedback=practiceGoal(model)?'같은 색의 중심 사이에 조각을 보냈어요! 실물 진도는 바뀌지 않았습니다.':'목표 조각과 이미 맞춘 부분을 함께 살펴보세요. 필요하면 한 수 되돌릴 수 있어요.';labDone=practiceGoal(model);moving=false;render();}
function undoLab(){if(!labSession||moving||preview||!state.history.length)return;model=Cube.fromString(state.history.pop().before);state.practice=model.asString();labDone=false;state.feedback='한 수 전이에요. 같은 조각의 색들이 함께 가는 길을 보세요.';render();}
function stopDemo(){demoToken++;preview=false;moving=false;model=Cube.fromString(state.practice);render();}
async function demo(){if(!state?.plan||state.stage>=8||state.stageReady||moving||busy||preview||loading)return;const token=++demoToken;demoStop=false;preview=true;model=Cube.fromString(state.current);const seq=moves();for(demoCursor=0;demoCursor<seq.length;demoCursor++){if(token!==demoToken)return;render();moving=true;await new Promise(r=>setTimeout(r,600));if(token!==demoToken)return;await turn(model,seq[demoCursor],'flow-cube');moving=false;if(token!==demoToken)return;if(demoStop){stopDemo();return;}}await new Promise(r=>setTimeout(r,900));if(token===demoToken)stopDemo();}
function count(){if(state.stage===0)return[4,5,6,7].filter(p=>{const i=model.ep.indexOf(p);return i<4&&model.eo[i]===0;}).length;if(state.stage===1)return[4,5,6,7].filter(p=>model.ep[p]===p&&model.eo[p]===0).length;if(state.stage===2)return[4,5,6,7].filter(p=>model.cp[p]===p&&model.co[p]===0).length;if(state.stage===3)return[8,9,10,11].filter(p=>model.ep[p]===p&&model.eo[p]===0).length;return null;}
function emptyPage(){return heading('내 큐브로 배우기','먼저 내 큐브 여섯 면을 촬영해요.','수업과 시범, 연습은 모두 촬영한 본인 큐브에서 시작합니다.')+'<section class="panel capture-required"><p>노랑 위·초록 앞에서 여섯 면을 등록하면, 내 배치에 필요한 초보자 순서로 안내해요.</p><a class="primary orange" href="#scan">내 큐브 촬영하기 →</a></section>';}
function sourceModal(){modal(`<h2>내가 촬영한 출발 상태</h2><p>사진에서 읽은 원래 배치예요. 현재 수업은 따라한 동작을 적용한 예상 상태입니다.</p><div class="source-cube-3d">${cubeHTML((labSession?.state||state).initial,'source-cube')}</div>`);}
function tools(){return`<details class="teacher-tools"><summary aria-label="수업 추가 도구">⋯</summary><div>${labSession?'<button id="lab-close-tools">실물 수업으로 돌아가기</button><button id="lab-reset">가상 연습 처음으로</button>':`<button id="teacher-demo" ${state.stageReady||state.stage>=8||state.offTrack?'disabled':''}>이번 조각 시범 보기</button><button id="lab-start" ${state.stage>=8||state.offTrack?'disabled':''}>내 큐브로 가상 연습</button><button id="teacher-rescan">현재 큐브 다시 촬영</button><button id="source-state">촬영한 출발 상태 보기</button>`}</div></details>`;}
function coach(){const course=CubeTeacher.courses[state.stage];if(state.offTrack)return`<div class="cube-coach teacher-coach"><div><small>화면과 실물 맞추기</small><b>이전 버전의 진행 중 동작을 보관했어요.</b><p>이전 동작으로 실물도 되돌리거나, 현재 큐브를 다시 촬영해주세요. 준비되지 않은 단계로 건너뛰지 않아요.</p></div></div>`;if(state.stageReady)return`<div class="cube-coach teacher-coach" role="status"><div><small>목표 완성</small><b>${course.title} 완성</b><p>${course.success}</p><p class="teacher-check">${state.stage<7?'실물도 같은 모양인지 보고, 다음 목표로 이어가요.':'여섯 면을 둘러보며 실물도 맞았는지 확인해주세요.'}</p></div></div>`;if(labSession&&!preview)return`<div class="cube-coach teacher-coach" role="status"><div><small>내 촬영 큐브의 이번 조각 시작 배치 · 가상 연습</small><b>${labDone?'✓ 연습 성공':targetColors()+'을 직접 보내보세요'}</b><p>${state.feedback||course.principle}</p><p class="teacher-check">실물 큐브는 돌리지 않아도 돼요. 실물 진도는 따로 보관 중입니다.</p></div></div>`;const i=instruction();return`<div class="cube-coach teacher-coach" role="status" aria-live="polite"><div><small>${preview?'시범 · 실물 진도에 반영하지 않아요':`이번 조각 ${i.step}/${i.total} · ${i.pattern} ${i.patternStep}/${i.patternLength}`}</small><b>${i.action}</b><p>${i.observe} ${i.reason}</p><p class="teacher-check">${state.feedback||i.check}</p></div></div>`;}
function controls(){if(preview)return'<div class="teacher-dock"><button class="primary" id="teacher-stop-demo">시범 끝내고 수업으로</button></div>';if(labSession)return practiceControls();const done=state.stage>=8;return`<div class="teacher-dock"><button id="teacher-prev" aria-label="이전 동작" ${!state.trail.length&&!state.history.length?'disabled':''}>‹</button><div><small>${done?'완성 확인':state.offTrack?'이전 동작 또는 다시 촬영':state.stageReady?'실물도 목표 모양이면 다음으로':'안내한 동작을 실물에 적용한 뒤 눌러요'}</small><button id="teacher-next" ${done||state.offTrack?'disabled':''}>${done?'여섯 면 완성':state.stageReady?(state.stage===7?'완성 확인':'다음 목표'):'따라했어요 · 다음'} <span>›</span></button></div></div>`;}
function practiceControls(){const faces=allFaces?FACES:[...new Set(moves().map(m=>m[0]))];const f=faces.includes(chosenFace)?chosenFace:faces[0];return`<div class="lab-controls"><div class="lab-faces">${faces.map(face=>`<button data-lab-face="${face}" aria-pressed="${f===face}"><i style="background:${COLORS[face]}"></i>${NAMES[face]}</button>`).join('')}<button id="lab-more" aria-label="다른 면 조작">⋯</button></div><div class="lab-turns">${['',"'",'2'].map(s=>`<button data-lab-turn="${f+s}" ${labDone?'disabled':''}>${s==='2'?'반 바퀴 180°':s==="'"?'↶ 반시계 90°':'↷ 시계 90°'}</button>`).join('')}</div><div class="lab-footer"><button id="lab-undo" ${!state.history.length?'disabled':''}>↶ 한 수 되돌리기</button><button id="lab-close">실물 수업으로 돌아가기</button></div></div>`;}
function loadingPage(){const course=CubeTeacher.courses[Math.min(7,state.stage)];return`<section class="teacher-class"><div class="teacher-heading"><div><small>내 촬영 큐브 · 같은 상태에서 이어가요</small><h1>${state.stage+1}/8 · ${course.title}</h1></div></div><div class="teacher-goal">${course.goal}</div><div class="teacher-stage"><div class="cube-coach teacher-coach" role="status"><div><b>${loading}</b><p>따라한 상태를 유지하고 다음 동작을 찾고 있어요.</p></div></div><div class="teacher-cube">${cubeHTML(model.asString(),'loading-cube')}</div></div><div class="teacher-dock"><button class="primary" disabled>동작 준비 중…</button></div></section>`;}
function page(){if(!state)return emptyPage();if(loading)return loadingPage();if(error)return`<section class="panel"><p class="error">${error}</p><button id="teacher-retry" class="primary">같은 상태로 다시 준비</button><button id="teacher-rescan" class="secondary">현재 큐브 다시 촬영</button></section>`;if(state.stage<8&&!state.plan&&!state.offTrack)return'<section class="panel teacher-loading">동작을 준비하고 있어요…</section>';const done=state.stage>=8,course=CubeTeacher.courses[Math.min(7,state.stage)],c=done?null:count();return`<section class="teacher-class ${labSession?'is-lab':''}"><div class="teacher-heading"><div><small>${labSession?'가상 연습 · 내 실물 진도 보관 중':'내 촬영 큐브 · 초보자 순서로 따라 맞추기'}</small><h1>${done?'여섯 면 완성':`${state.stage+1}/8 · ${course.title}`}</h1></div>${tools()}</div><div class="teacher-goal"><span>${done?'실물도 여섯 면이 맞는지 확인해주세요.':course.goal}</span>${c!==null?`<b>${c}/4</b>`:''}</div><div class="teacher-stage">${done?'<div class="cube-coach teacher-coach"><div><b>중심색으로 조각의 집을 찾으며 완성했어요.</b><p>화면은 따라한 회전의 예상 상태예요. 실물과 다르면 이전 동작 또는 다시 촬영으로 맞춰주세요.</p></div></div>':coach()}<div class="teacher-cube">${cubeHTML(model.asString(),'flow-cube')}</div><span class="teacher-view-note">노랑 위·흰색 아래 · 회전은 돌릴 중심면을 정면에서 본 기준</span></div>${controls()}</section>`;}
function practicePage(){if(!state)return emptyPage();if(!labSession&&!loading&&state.plan&&state.stage<8)labStart();if(!labSession&&state.stage>=8)return'<section class="panel capture-required"><h1>현재 큐브는 이미 완성됐어요.</h1><p>다른 문제를 만들지 않습니다. 연습할 내 큐브의 현재 배치를 촬영해주세요.</p><a class="primary orange" href="#scan">내 큐브 촬영</a></section>';return page();}
function decorate(){const el=document.getElementById('flow-cube');if(!el)return;el.style.transform=cameraForFace(view);if(state.stage>=8||state.offTrack)return;const target=targetIndices(),dest=destination(),m=!labSession||preview?moves()[preview?demoCursor:state.guideCursor]:null;[...el.querySelectorAll('.sticker')].forEach((t,i)=>{const f=FACES[Math.floor(i/9)],e=E.find(a=>a.includes(i)),c=C.find(a=>a.includes(i));t.setAttribute('aria-label',i%9===4?NAMES[f]+' 중심':colorsOf(model,e||c||[i])+' '+(e?'변 조각':c?'꼭짓점 조각':'중심'));if(!state.stageReady&&target.includes(i)){t.classList.add('first-target');t.innerHTML='<span>◎</span>';}if(!state.stageReady&&dest.includes(i)&&!target.includes(i)){t.classList.add('flow-destination');t.innerHTML='<span>자리</span>';}if(m&&i===FACES.indexOf(m[0])*9+4){t.classList.add('cross-center');t.innerHTML='<span>'+NAMES[m[0]]+'</span>';}});if(m&&!state.stageReady)drawArrow(el,m);}
function bind(){const on=(id,fn)=>{const b=document.getElementById(id);if(b)b.onclick=fn;};on('teacher-retry',()=>{prepare();render();});on('teacher-rescan',()=>{if(moving)return;if(labSession)leaveLab(false);beginRescan();});on('source-state',sourceModal);on('teacher-prev',previous);on('teacher-next',next);on('teacher-demo',demo);on('teacher-stop-demo',()=>{if(moving)demoStop=true;else stopDemo();});on('lab-start',()=>{if(labStart())location.hash='#practice';});on('lab-close',()=>leaveLab());on('lab-close-tools',()=>leaveLab());on('lab-reset',()=>{if(moving)return;model=Cube.fromString(state.current);state.practice=state.current;state.history=[];state.feedback='';labDone=false;render();});on('lab-more',()=>{if(moving)return;allFaces=!allFaces;render();});on('lab-undo',undoLab);document.querySelectorAll('[data-lab-face]').forEach(b=>b.onclick=()=>{if(moving)return;chosenFace=b.dataset.labFace;render();});document.querySelectorAll('[data-lab-turn]').forEach(b=>b.onclick=()=>act(b.dataset.labTurn));if(state&&!loading&&!error)decorate();}
function clear(){cancelJob();demoToken++;state=null;model=null;labSession=null;loading='';error='';preview=false;moving=false;}

function fixedEdges(c,ids){return ids.every(i=>c.ep[i]===i&&c.eo[i]===0);}
function fixedCorners(c,ids){return ids.every(i=>c.cp[i]===i&&c.co[i]===0);}
function milestone(c,n){if(n===0)return[4,5,6,7].every(p=>{let i=c.ep.indexOf(p);return i<4&&c.eo[i]===0;});if(n===1)return fixedEdges(c,[4,5,6,7]);if(n===2)return milestone(c,1)&&fixedCorners(c,[4,5,6,7]);if(n===3)return lower(c);if(n===4)return lower(c)&&c.eo.slice(0,4).every(v=>v===0);if(n===5)return milestone(c,4)&&c.co.slice(0,4).every(v=>v===0);if(n===6)return milestone(c,5)&&c.cp.every((p,i)=>p===i);return c.isSolved();}
function detect(c){if(c.isSolved())return 8;for(let n=6;n>=1;n--)if(milestone(c,n))return n+1;return milestone(c,0)?1:0;}
function targetIndices(c=model){const d=descriptor();if(d.piece!=null)return(d.kind==='corner'?C:E)[(d.kind==='corner'?c.cp:c.ep).indexOf(d.piece)];return(d.kind==='corner'?C:E).slice(0,4).flat();}
function destination(){const d=descriptor();if(state.stage===0){const end=Cube.fromString(segment().final);return E[end.ep.indexOf(d.piece)];}if(state.stage===1)return E[d.piece-4];if(d.piece!=null)return(d.kind==='corner'?C:E)[d.piece];return(d.kind==='corner'?C:E).slice(0,4).flat();}
function segmentGoal(c,n,d,initial){if(n===0){const isPetal=(x,p)=>{let i=x.ep.indexOf(p);return i<4&&x.eo[i]===0;};return isPetal(c,d.piece)&&[4,5,6,7].filter(p=>isPetal(initial,p)).every(p=>isPetal(c,p));}if(n===1){const fixed=[4,5,6,7].filter(i=>initial.ep[i]===i&&initial.eo[i]===0);const locked=[d.piece,...fixed],remaining=[4,5,6,7].filter(p=>!locked.includes(p));return fixedEdges(c,locked)&&remaining.every(p=>{const i=c.ep.indexOf(p);return i<4&&c.eo[i]===0;});}if(n===2){const fixed=[4,5,6,7].filter(i=>initial.cp[i]===i&&initial.co[i]===0);return milestone(c,1)&&fixedCorners(c,[d.piece,...fixed]);}if(n===3){const fixed=[8,9,10,11].filter(i=>initial.ep[i]===i&&initial.eo[i]===0);return milestone(c,2)&&fixedEdges(c,[d.piece,...fixed]);}return milestone(c,n);}
function colorsOf(c,indices){return[...new Set(indices.map(i=>NAMES[c.asString()[i]]))].join('·');}
function cameraForFace(f){const down=f.endsWith('-low');f=f.replace('-low','');return f==='U'?'rotateX(-75deg) rotateY(0deg)':f==='D'?'rotateX(75deg) rotateY(0deg)':`rotateX(${down?24:-24}deg) rotateY(${{F:-25,R:-115,L:65,B:155}[f]}deg)`;}
function drawArrow(el,m){const f=m[0],tr={F:'translateZ(80px)',R:'rotateY(90deg) translateZ(80px)',L:'rotateY(-90deg) translateZ(80px)',B:'rotateY(180deg) translateZ(80px)',U:'rotateX(90deg) translateZ(80px)',D:'rotateX(-90deg) translateZ(80px)'}[f];el.insertAdjacentHTML('beforeend',`<div class="face-rotation" style="transform:${tr}" aria-hidden="true" data-move="${m}"><svg viewBox="0 0 100 100" style="${m.includes("'")?'transform:scaleX(-1)':''}"><path d="M26 22 A37 37 0 1 1 15 57" fill="none" stroke="#f6863f" stroke-width="6" stroke-linecap="round"/><path d="M6 63 L13 43 L27 59" fill="#f6863f"/>${m.includes('2')?'<text x="32" y="55" fill="#fff5cf" font-size="16" font-weight="bold">180°</text>':''}</svg></div>`);}

state=read('camera');if(state)restore();
return{page,practicePage,bind,openCaptured,leaveLab,clear,position:()=>window.scrollTo(0,0),start:()=>{if(state){restore();routeToLesson();}else location.hash='#scan';},tests:{milestone,detect,read,segmentGoal,migrate,next,previous,labStart,leaveLab,act,undoLab,demo,stopDemo,restore,snapshot:()=>({state:state?JSON.parse(JSON.stringify(state)):null,cube:model?.asString(),inLab:!!labSession,preview,loading,error,instruction:state?.plan&&state.stage<8&&!state.stageReady&&!state.offTrack?instruction():null})}};
})();